#!/usr/bin/env bash
# Vynix Hosting Panel - One-command installer
# Usage: bash <(curl -sL https://raw.githubusercontent.com/OpRGamerz15/VynixPanel/main/install.sh)

set -euo pipefail

echo "=== Vynix Hosting Panel Installer ==="

# Create directory
INSTALL_DIR="${HOME}/vynix-panel"
mkdir -p "$INSTALL_DIR"
cd "$INSTALL_DIR"

echo "[1/3] Extracting files..."

# Embedded base64 archive
base64 -d << 'B64_EOF' | tar -xzf -

B64_EOF

echo "[2/3] Making setup executable..."
chmod +x setup.sh

echo "[3/3] Starting setup menu..."
echo ""
exec ./setup.sh
